with candidate (n, title, artist, image_url, content, image_license, image_credit, image_page) as (
    values
    (1, 'ホイッスルジャケット', 'ジョージ・スタッブズ', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/Whistlejacket_by_George_Stubbs.jpg/960px-Whistlejacket_by_George_Stubbs.jpg', '18世紀イギリスの動物画家ジョージ・スタッブズが、第2代ロッキンガム侯爵の依頼で描いたアラブ種の競走馬ホイッスルジャケットの肖像です。高さ約3メートルの画面に、後脚で立ち上がる馬をほぼ等身大で描き、背景には何も描いていません。スタッブズは馬の解剖を長年研究して『馬の解剖学』を出版しており、筋肉や血管まで確かにとらえた描写にその成果が表れています。ロンドンのナショナル・ギャラリーが所蔵しています。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Whistlejacket_by_George_Stubbs.jpg'),
    (2, '百駿図', '郎世寧', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/A_Hundred_Steeds.jpg/960px-A_Hundred_Steeds.jpg', 'イタリア出身のイエズス会士で、清の宮廷画家として活躍した郎世寧（ジュゼッペ・カスティリオーネ）の代表作です。1728年に完成した長い絵巻で、草原で休み、草をはみ、水辺で戯れる100頭の馬を描いています。西洋の陰影法や遠近法を、絹に描く中国の伝統的な画材と組み合わせ、立体感のある馬と奥行きのある風景を生み出しました。東西の絵画を融合させた宮廷絵画の傑作で、台北の国立故宮博物院が所蔵しています。', 'Public domain', null, 'https://commons.wikimedia.org/wiki/File:A_Hundred_Steeds.jpg')
), fresh as (
    select c.*, row_number() over (order by c.n) as k
    from candidate c
    where not exists (select 1 from public.daily_columns d where d.title = c.title)
), free_day as (
    select day::date as display_date, row_number() over (order by day) as k
    from generate_series(
        (now() at time zone 'Asia/Tokyo')::date,
        (now() at time zone 'Asia/Tokyo')::date + 2
            + (select count(*)::int from public.daily_columns
               where display_date >= (now() at time zone 'Asia/Tokyo')::date),
        interval '1 day') as day
    where not exists (select 1 from public.daily_columns d where d.display_date = day::date)
)
insert into public.daily_columns (title, artist, image_url, content, image_license, image_credit, image_page, display_date)
select f.title, f.artist, f.image_url, f.content, f.image_license, f.image_credit, f.image_page, d.display_date
from fresh f join free_day d using (k)
on conflict (display_date) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('根津美術館で「彫る漆」、填漆の重文を初公開', '東〜東南アジアの「彫る」漆工技法を体系的に紹介。収蔵後初公開の重要文化財も並ぶ。', '東京・南青山の根津美術館で、漆工技法のうち「彫る」表現に焦点を当てた企画展「彫る漆」が12月5日から2027年1月17日まで開かれる。館蔵品を中心に漆の装飾と技法を紹介するシリーズの第5弾で、彫漆、彫木彩漆（鎌倉彫）、鎗金、沈金、填漆、蒟醤といった東〜東南アジアで生まれた技法を体系的に紹介する。中国・明時代の《椿堆朱合子》や《龍鎗金硯箱》などが並び、明時代前期の填漆の作例である重要文化財《楼閣人物填漆箪笥》は収蔵後初めて公開される。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33363',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.trending_articles (title, summary, content, image_url, keyword, source_url,
    image_license, image_credit, image_page)
values ('「恵比寿映像祭2027」、テーマは「あそびのルール」', '東京都写真美術館などで2027年2月5日から21日まで。光学玩具からゲーム作品までをたどる。', '東京都写真美術館を中心に、映像とアートの国際フェスティバル「恵比寿映像祭2027」が2027年2月5日から21日まで開催される。2009年の第1回以来、展示、上映、ライブ・パフォーマンス、トークなどを複合的に行ってきた映像祭で、今回の総合テーマは「あそびのルール｜Rules of Play」。18〜19世紀のピープショーや光学玩具から現代の映像作品、ゲーム作品までをたどり、ルールが生み出すあそびの仕組みと、その背後にある社会に目を向ける。出品予定作家には田中功起、谷口暁彦、クリス・マルケルらが名を連ねる。入場は無料（上映と一部イベントは有料）。', '', '展覧会', 'https://bijutsutecho.com/magazine/news/exhibition/33376',
        null, null, null)
on conflict (source_url) do nothing;

insert into public.artworks (title, title_en, artist, artist_en, year, movement_slug, collection, image_url, content,
    image_license, image_credit, image_page)
values ('野うさぎ', 'Young Hare', 'アルブレヒト・デューラー', 'Albrecht Dürer',
        1502,
        (select slug from public.art_movements where slug = 'renaissance'),
        'アルベルティーナ美術館', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/Albrecht_D%C3%BCrer_-_Hare%2C_1502_-_Google_Art_Project.jpg/960px-Albrecht_D%C3%BCrer_-_Hare%2C_1502_-_Google_Art_Project.jpg', 'アルブレヒト・デューラーが1502年に水彩とグワッシュで描いた、うずくまる野うさぎの習作です。毛の一本一本を細い筆で描き分け、瞳には窓の映り込みとされる光まで描かれています。北方の精密な描写の伝統を受け継ぎながら、イタリアで触れた自然研究の姿勢を動物にまで広げた作品で、ルネサンスの画家たちが自然を細かく観察して描いたことをよく示しています。光に弱いため展示の機会は限られ、ウィーンのアルベルティーナ美術館が所蔵しています。',
        'Public domain', null, 'https://commons.wikimedia.org/wiki/File:Albrecht_Dürer_-_Hare,_1502_-_Google_Art_Project.jpg')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

