        null,
        (select slug from public.art_movements where slug = 'kano'),
        'クリーブランド美術館', 'https://openaccess-cdn.clevelandart.org/1987.9/1987.9_web.jpg', '安土桃山時代から江戸時代初期に活躍した狩野山楽による、墨で描いた六曲一双の屏風です。水辺でくつろぐ雁の群れを、古典や宗教の主題に結びつけずに描いています。雁は13世紀ごろから日本の水墨画に現れ、中国の禅僧画家たちの画風とともに尊ばれてきました。永徳の門下で色鮮やかな大画面も多く手がけた山楽が、ここでは初期の水墨画の様式に敬意を払っており、狩野派が漢画の伝統を受け継いでいたことがわかります。クリーブランド美術館が所蔵しています。',
        'CC0', 'The Cleveland Museum of Art', 'https://clevelandart.org/art/1987.9')
on conflict (title, artist) do update set
    title_en = excluded.title_en,
    artist_en = excluded.artist_en,
    year = excluded.year,
    movement_slug = coalesce(excluded.movement_slug, public.artworks.movement_slug),
    collection = excluded.collection,
    image_url = excluded.image_url,
    content = excluded.content,
    image_license = excluded.image_license,
    image_credit = excluded.image_credit,
    image_page = excluded.image_page;

