insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('狩野山楽', 'Kanō Sanraku', '山楽',
        1559, 1635, 'japan', array['kano']::text[],
        '狩野永徳の門下で豊臣家に仕え、京都にとどまって「京狩野」の祖となった絵師。', '1559年、近江国に浅井長政の家臣・木村永光の子として生まれました。浅井氏が滅びた後に豊臣秀吉に仕え、秀吉の命で狩野永徳の門下に入り、狩野の姓を許されたと伝わります。

1590年、永徳が東福寺法堂の天井画の制作中に病に倒れると、秀吉の命で山楽が引き継いで完成させ、永徳の後継者として期待されました。秀吉・秀頼の2代に仕え、障壁画や屏風に永徳風の力強い作品を残しています。大坂の陣の後は豊臣方とみなされて窮地に陥りましたが、九条幸家らの助命嘆願で救われました。

慶長末年には大覚寺宸殿の障壁画を手がけました。狩野本家が江戸へ移った後も京都にとどまり、娘婿の狩野山雪をはじめ、京都に残った山楽の子孫は「京狩野」と呼ばれました。', 'https://ja.wikipedia.org/wiki/%E7%8B%A9%E9%87%8E%E5%B1%B1%E6%A5%BD')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();

insert into public.artists (name, name_en, short_name, born, died, region, movement_slugs, summary, body, source_url)
values ('梁楷', 'Liang Kai', '梁楷',
        null, null, 'east_asia', array['song-yuan']::text[],
        '減筆体の人物画で知られ、日本の水墨画に大きな影響を与えた南宋の画家。', '中国・南宋の画家で、生没年はわかっていません。東平府須城県の出身とされ、13世紀初めの嘉泰年間に、宮廷画家の最高位である画院待詔となりました。

皇帝から金帯を賜ったものの関心を示さず、柱に掛けて帰ったと伝えられます。酒を好み、画院の画家としては型破りな人柄で、「梁風子」と号しました。細密な院体画を描く一方で、少ない筆数で人物をとらえる「減筆体」と呼ばれる粗放な人物画を得意としました。

代表作に東京国立博物館の国宝「出山釈迦図」「雪景山水図」、重要文化財「李白吟行図」、台北の国立故宮博物院の「潑墨仙人図」があります。出山釈迦図などは足利将軍家の東山御物として伝わり、梁楷は牧谿・玉澗とともに日本の水墨画に大きな影響を与えました。', 'https://ja.wikipedia.org/wiki/%E6%A2%81%E6%A5%B7')
on conflict (name) do update set
    name_en = excluded.name_en,
    short_name = excluded.short_name,
    born = excluded.born,
    died = excluded.died,
    region = excluded.region,
    movement_slugs = excluded.movement_slugs,
    summary = excluded.summary,
    body = excluded.body,
    source_url = excluded.source_url,
    updated_at = now();
